var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that the original behavior is preserved
    // The change replaces a series of if-else if statements with a loop
    // We need to verify that the unit selection logic is identical

    // Test a value that should be exactly at the boundary of KB
    // In original code: mag >= map.kb would trigger 'KB'
    // In new code: the loop checks PB, TB, GB, MB, then KB
    // So same behavior

    // But let's test a case where the order matters
    // The original code checks in descending order: PB, TB, GB, MB, KB, B
    // The new code does the same via the array

    // Test a value that is exactly 1 KB
    assert.strictEqual(bytes(1024, { unit: 'kb' }), '1.00 KB');

    // Test a value that is just below 1 KB
    assert.strictEqual(bytes(1023, { unit: 'kb' }), '1.00 KB');

    // Test a value that is exactly 1 MB
    assert.strictEqual(bytes(1048576, { unit: 'mb' }), '1.00 MB');

    // Now test a value that is just below 1 MB but above 1 KB
    // This should still be KB, not MB
    assert.strictEqual(bytes(1048575, { unit: 'kb' }), '1024.00 KB');

    // The key test: does the new code correctly skip units that are too large?
    // Let's test a value that is 1 PB
    assert.strictEqual(bytes(1125899906842624, { unit: 'pb' }), '1.00 PB');

    // Now test a value that is just below 1 PB
    assert.strictEqual(bytes(1125899906842623, { unit: 'pb' }), '1024.00 TB');

    // The critical case: a value that is exactly 1 TB
    assert.strictEqual(bytes(1099511627776, { unit: 'tb' }), '1.00 TB');

    // And just below 1 TB
    assert.strictEqual(bytes(1099511627775, { unit: 'tb' }), '1024.00 GB');

    // The change is equivalent: both versions check in descending order
    // The array is ordered PB, TB, GB, MB, KB
    // The original if-else chain also checks in descending order
    // So the logic is identical

    // Therefore, this is an equivalent refactor
  });
});

